// ============================================================
// Cosmos DB EF Core 9 Breaking Change Fixes
// Apply these patterns in your separate Cosmos DB project.
// ============================================================

using Microsoft.EntityFrameworkCore;

// --- Fix 1: Discriminator property renamed from "Discriminator" to "$type" ---
// Existing documents use "Discriminator". Explicitly configure to preserve compatibility.
//
// --- Fix 2: id property no longer contains discriminator ---
// EF Core 8 stored id as "EntityType|KeyValue" (e.g., "Session|123").
// EF Core 9 stores just "123". Opt in to old format for existing data.

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve old discriminator property name for existing documents
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Preserve old compound id format ("Session|123") for existing documents
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public int Id { get; set; }
    public string? Name { get; set; }
}

// --- Fix 3: Sync I/O no longer supported on Cosmos DB provider ---
// Synchronous methods (ToList, SaveChanges, etc.) now throw.
// Replace all sync calls with async equivalents.

class CosmosQueryService
{
    // BREAKS in EF Core 9:
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // Fix — use async methods:
    async Task Example(CosmosDbContext db)
    {
        var sessions = await db.Sessions.ToListAsync();
        await db.SaveChangesAsync();
    }
}

